spec.expr:
histogram_quantile(
  0.5,
  sum by (operation, le) (
    rate(cadence_latency_per_tl_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-matching|cadence_matching",
      operation=~"$procedure",
      domain=~"$domain",
      tasklist=~"$tasklist"
    }[$__rate_interval])
  )
)

100 * (
  1 -
  (
    (
      sum by (operation) (
        rate(cadence_errors_per_tl{
          deployment=~"$deployment",
          cadence_service=~"cadence-matching|cadence_matching",
          operation=~"$procedure",
        }[$__rate_interval])
      )
      or on (operation)
      (
        sum by (operation) (
          rate(cadence_requests_per_tl{
            deployment=~"$deployment",
            cadence_service=~"cadence-matching|cadence_matching",
            operation=~"$procedure",
          }[$__rate_interval])
        ) * 0
      )
    )
    /
    sum by (operation) (
      rate(cadence_requests_per_tl{
        deployment=~"$deployment",
        cadence_service=~"cadence-matching|cadence_matching",
        operation=~"$procedure",
      }[$__rate_interval])
    )
  )
)

histogram_quantile(
  0.5,
  sum by (operation, le) (
    rate(cadence_latency_per_tl_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-matching|cadence_matching",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.99,
  sum by (operation, le) (
    rate(cadence_latency_per_tl_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-matching|cadence_matching",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.999,
  sum by (operation, le) (
    rate(cadence_latency_per_tl_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-matching|cadence_matching",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.99,
  sum by (operation, le) (
    rate(cadence_latency_per_tl_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-matching|cadence_matching",
      operation=~"$procedure",
      domain=~"$domain",
      tasklist=~"$tasklist"
    }[$__rate_interval])
  )
)

sum(
  rate(syncmatch_latency_per_tl_ns_count{
    cadence_service=~"cadence-matching|cadence_matching",
    deployment=~"$deployment",
    domain=~"$domain",
    tasklist=~"$tasklist",
    operation="AddActivityTask"
  }[1m])
)
/
sum(
  rate(cadence_requests_per_tl{
    cadence_service=~"cadence-matching|cadence_matching",
    deployment=~"$deployment",
    domain=~"$domain",
    tasklist=~"$tasklist",
    operation="AddActivityTask"
  }[1m])
)

spec.m3ql_original:
total = fetch service:$service deployment:$deployment domain:$domain tasklist:$tasklist name:cadence_requests_per_tl operation:addactivitytask | transformNull 0 | scaleToSeconds 1 | sum | summarize 1m sum;
sync = fetch service:$service deployment:$deployment domain:$domain tasklist:$tasklist name:syncmatch_latency_per_tl_ns operation:addactivitytask | removeEmpty | sum name | scaleToSeconds 1 | summarize 1m sum;
sync | asPercent (total) | alias "syncMatchRate"

